type TreeStatus = 'healthy' | 'at-risk' | 'dead' | 'orphaned';
type CheckpointStatus = 'verified' | 'self-reported' | 'missed' | 'mismatch';
type EvidenceType = 'photo' | 'video' | 'note';

type Checkpoint = {
  date: string;
  verifier: string;
  status: CheckpointStatus;
  evidenceType: EvidenceType;
  evidenceUrl: string;
  note: string;
};

type CustodyEvent = {
  date: string;
  from: string;
  to: string;
  reason: string;
};

type Tree = {
  id: string;
  species: string;
  plantedAt: string;
  zone: string;
  coordinates: [number, number];
  status: TreeStatus;
  custodian: string;
  group: string;
  checkpoints: Checkpoint[];
  custodyHistory: CustodyEvent[];
};

type KuriGroup = {
  id: string;
  name: string;
  zone: string;
  trustScore: number;
  members: string[];
  checkpointCount: number;
  payoutHistory: { month: string; amount: string; note: string }[];
};

type RiskItem = {
  id: string;
  type: 'orphaned' | 'missed checkpoint' | 'mismatch';
  treeId: string;
  severity: 'high' | 'medium' | 'low';
  description: string;
};

